import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"商誉与减值","description":"","frontmatter":{"title":"商誉与减值","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/goodwill-impairment.md","filePath":"quant/goodwill-impairment.md","lastUpdated":1789023840000}'),E={name:"quant/goodwill-impairment.md"};function c(m,a,A,u,_,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="商誉与减值" tabindex="-1">商誉与减值 <a class="header-anchor" href="#商誉与减值" aria-label="Permalink to &quot;商誉与减值&quot;">​</a></h1><div class="epigraph"><p>外购商誉先把并购溢价记成资产；减值再一次性打回利润。价值与质量因子会在并购年变「厚」、在减值年变「差」。</p><footer>—— 据 SFAS 142 / IAS 36 的减值逻辑；Penman 对收购会计与商誉的讨论整理</footer></div><p>上一课<a href="/quant/buyback-dividend">回购与分红</a>处理的是内部资本退出。并购是相反方向：现金或股份出去，账上出现商誉。上一课<a href="/quant/book-intangibles">账面价值与无形资产</a>已指出外购商誉进账面、自制品牌不进。本课补商誉的后续计量：不摊销而减值时，利润与账面如何一起跳，以及回测如何避免用后来的减值去改写并购当年的质量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>并购完成日，购买价超过可辨认净资产公允价值的部分记入商誉，账面立刻变厚，应计与资产增速一起变大。之后若测试认为可回收金额低于账面，减值计入当期利润，质量与盈利因子在减值年变差。若用 restated 表把减值追溯调到并购年，等于用后来才承认的失败去重写当时可交易的厚账面。缺口是把商誉当成<strong>带事件日期的估计资产</strong>，而不是永恒的经济品牌。</p><h3 id="减值不是经营亏损的平滑版" tabindex="-1">减值不是经营亏损的平滑版 <a class="header-anchor" href="#减值不是经营亏损的平滑版" aria-label="Permalink to &quot;减值不是经营亏损的平滑版&quot;">​</a></h3><p>经营亏损逐期发生；减值是估计的一次性向下修正，常滞后于经济恶化。把减值加回利润「看经常性盈利」有时合理，但若同时保留减值前的厚账面去做价值，就会一边当利润是暂时的、一边当资产是永久的。加回必须在利润与账面两侧同时声明，不能只美化盈利因子。</p><p><span class="marginnote">SFAS 142 之后美国商誉不再定期摊销，改为至少年度减值测试。摊销时代与减值时代的时间序列不可直接拼接成同一个质量因子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PIT 规则：并购完成且报表披露后，商誉进入账面；减值只在公告减值的那个期间进入利润与资产，不回写以前期间。因子若使用「减值前利润」，要同步提供「减值前账面」或把商誉从账面剔除，否则分子分母不配对。当时宇宙仍含后来因并购失败而退市的公司。</p><p>识别上，现金流量表与附注的减值行比利润表「特别项目」更稳。可用日期用减值公告或季报公告，不是审计报告日后的 vendor 修订日。</p>',11)),(e(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20DEAL%5B%22%E5%B9%B6%E8%B4%AD%E5%AE%8C%E6%88%90%22%5D%20--%3E%20GW%5B%22%E5%95%86%E8%AA%89%E5%85%A5%E8%B4%A6%22%5D%0A%20%20GW%20--%3E%20THICK%5B%22%E8%B4%A6%E9%9D%A2%E5%8F%98%E5%8E%9A%22%5D%0A%20%20TEST%5B%22%E5%87%8F%E5%80%BC%E6%B5%8B%E8%AF%95%22%5D%20--%3E%20IMP%5B%22%E5%87%8F%E5%80%BC%E8%AE%A1%E5%85%A5%E5%88%A9%E6%B6%A6%22%5D%0A%20%20IMP%20--%3E%20THIN%5B%22%E8%B4%A6%E9%9D%A2%E6%89%93%E8%96%84%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>减值测试滞后于价格：市场往往先把收购方打下去，会计随后确认。回测若在减值公告前就用后来的减值金额调薄账面，价值因子会在下跌已经发生后才显得「更便宜是假的」——这是用未来会计解释过去价格。正确顺序是：当时厚账面参与当时排序，减值只进入公告期的利润与资产，两边都走可用日期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>商誉让价值因子在收购方一侧机械变「便宜」（账面升、若市场尚未完全消化则账面市值升），让投资/资产增长因子变「高投资」。减值年则制造巨大的负盈利与负应计。市场往往在减值公告前已下跌，于是质量空头会看起来能预测减值——其中一块其实是价格已经反映的滞后会计确认。事件课会把业绩公告当窗口；减值公告是同类事件，只是科目更极端。</p><p><span class="marginnote">用后来的减值回填并购年账面，是典型的 restated 前视：当时交易者拿到的是厚账面，不是已经被打薄的终局账面。</span></p><p>并购完成日之后，商誉按当时报表进入账面与资产增长；减值只在减值公告所属期进入利润。复制投资因子时，把「含商誉资产增长」与「剔商誉资产增长」并排，避免把收购会计当成 capex。若策略加回减值「看经常性利润」，必须在同一张卡上声明账面是否仍含商誉，否则盈利被美化、价值被加厚，两边讨好。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不讲购买法与权益结合法的历史全文，不估并购协同。少数股东与合并范围交给<a href="/quant/nci-consolidation">合并与少数股东</a>。后课税率会再碰到减值的税盾。后课默认：商誉按披露时点进出账面；减值不追溯改写因子历史。</p><p>后课税率会碰到减值的税盾，分析师惊喜会碰到「是否加回减值」的口径战。本课要求：减值按公告期进入，不追溯；加回必须利润与账面成对声明。收购会计把投资、价值、质量绑在一起的那一年，来源卡上的并购标记就是为了让你看见共线，而不是再开一个「并购因子」。</p><p>后课默认商誉按披露时点进出账面，减值不追溯改写并购年的价值与投资因子。</p><p>收购完成到首次把商誉写进可用来源卡的报表之间，仍有可用日期滞后：不得在成交公告日就把尚未入表的商誉加进账面去做当周 HML。减值反向同样：只有公告期的利润与资产被改写。</p><p>摊销制与减值制的样本不要拼成同一质量时间序列；准则切换年单独标记，与租赁入表是同一类会计跳变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外购商誉使账面与资产增长在并购年跳升。</li><li>减值把估计失败一次性打进利润，质量因子会跳。</li><li>加回减值利润时，账面侧也要声明是否剔除商誉。</li><li>用终局减值重写并购年是 PIT 违规。</li><li>摊销制与减值制不可混成同一时间序列。</li><li>出处：SFAS 142 / IAS 36；Penman 收购会计讨论。</li></ul>',13))])}const T=o(E,[["render",c]]);export{B as __pageData,T as default};
